statement:
The string `s` is a balanced sequence of `(` and `)`. Return its score, defined recursively:

- the pair `()` alone is worth 1;
- two balanced strings written one after the other, `AB`, are worth the score of `A` plus the score of `B`;
- a balanced string wrapped in one more pair, `(A)`, is worth twice the score of `A`.

validator:
function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 50) return 's needs 2 to 50 characters.';
  if (!/^[()]+$/.test(s)) return "s may contain only '(' and ')'.";
  let depth = 0;
  for (const ch of s) {
    depth += ch === '(' ? 1 : -1;
    if (depth < 0) return 's must be balanced.';
  }
  return depth === 0 ? null : 's must be balanced.';
}

