function scoreOfParentheses(s) {
  // Follow the grammar directly: split into top-level groups, then unwrap each one.
  const score = (text) => {
    let total = 0, depth = 0, begin = 0;
    for (let i = 0; i < text.length; i++) {
      depth += text[i] === '(' ? 1 : -1;
      if (depth === 0) {
        const body = text.slice(begin + 1, i);
        total += body.length === 0 ? 1 : 2 * score(body);
        begin = i + 1;
      }
    }
    return total;
  };
  return score(s);
}

