function generate(rand, size) {
  const pairs = size === 'large' ? 18 + Math.floor(rand() * 8) : 1 + Math.floor(rand() * 7);
  const style = rand();
  if (style < 0.15) return ['('.repeat(pairs) + ')'.repeat(pairs)];
  if (style < 0.25) return ['()'.repeat(pairs)];
  // Random walk: open while pairs remain, close while something is open, with a bias that sets the depth.
  const bias = 0.3 + rand() * 0.5;
  let s = '', open = 0, left = pairs;
  while (left > 0 || open > 0) {
    if (left > 0 && (open === 0 || rand() < bias)) { s += '('; open++; left--; }
    else { s += ')'; open--; }
  }
  return [s];
}
